INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist Compliance nur für große Firmen relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Gilt für alle Größen"}, {"text": "Ja", "correct": false, "because": "Auch KMUs betroffen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit diesen Regeln?', 3, '[{"text": "Rechtliche Absicherung", "correct": true, "because": "Vermeidet Strafen"}, {"text": "Maximale Performance", "correct": false, "because": "Nicht primär"}, {"text": "Kosten senken", "correct": false, "because": "Kann teuer sein"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Bereiche fallen unter diese Vorgaben?', 5, '[{"text": "Datenschutz", "correct": true, "because": "Schützt personenbezogene Daten"}, {"text": "IT-Sicherheit", "correct": true, "because": "Sichert Systeme"}, {"text": "Servergeschwindigkeit", "correct": false, "because": "Kein Fokus"}, {"text": "UI-Design", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Compliance schützt vor Bußgeldern. b) Sie ist optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Pflicht in vielen Branchen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Umsetzung?', 4, '[{"text": "Gesetzliche Vorgaben", "correct": false, "because": "Kern der Regeln"}, {"text": "Dokumentation", "correct": false, "because": "Nachweis nötig"}, {"text": "Firmenlogo", "correct": true, "because": "Kein rechtlicher Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Compliance nur IT betrifft?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Finanzen, Personal"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Regelung ist ein typisches Beispiel?', 3, '[{"text": "DSGVO", "correct": true, "because": "Datenschutz in der EU"}, {"text": "HTML5", "correct": false, "because": "Technischer Standard"}, {"text": "ISO 9001", "correct": false, "because": "Qualitätsmanagement"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen sichern diese Vorgaben?', 5, '[{"text": "Schulungen", "correct": true, "because": "Sensibilisiert Mitarbeiter"}, {"text": "Audits", "correct": true, "because": "Prüft Einhaltung"}, {"text": "Schnelle Server", "correct": false, "because": "Kein direkter Schutz"}, {"text": "Neue Hardware", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Compliance kostet immer Geld. b) Sie gilt nur für Daten. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch Prozesse betroffen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Einhaltung?', 4, '[{"text": "Richtlinien", "correct": false, "because": "Leitfaden nötig"}, {"text": "Überwachung", "correct": false, "because": "Sichert Umsetzung"}, {"text": "Spielekonsole", "correct": true, "because": "Kein Zusammenhang"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Compliance freiwillig?', 2, '[{"text": "Nein", "correct": true, "because": "Gesetzlich oft vorgeschrieben"}, {"text": "Ja", "correct": false, "because": "Pflicht in vielen Fällen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bringt mir die Einhaltung?', 4, '[{"text": "Vertrauen der Kunden", "correct": true, "because": "Zeigt Seriosität"}, {"text": "Rechtssicherheit", "correct": true, "because": "Vermeidet Strafen"}, {"text": "Schnellere Prozesse", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass es nur für Banken gilt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Alle Branchen betroffen"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Umsetzung?', 3, '[{"text": "Risikoanalyse", "correct": true, "because": "Identifiziert Schwachstellen"}, {"text": "Schnelle Umsetzung", "correct": false, "because": "Qualität zählt"}, {"text": "Minimale Kosten", "correct": false, "because": "Sicherheit wichtiger"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Sie erfordert Dokumentation. b) Sie ist einmalig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kontinuierlicher Prozess"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rollen sind bei der Umsetzung wichtig?', 5, '[{"text": "Compliance Officer", "correct": true, "because": "Koordiniert Maßnahmen"}, {"text": "IT-Abteilung", "correct": true, "because": "Technische Umsetzung"}, {"text": "Marketing", "correct": false, "because": "Kein direkter Einfluss"}, {"text": "Rezeption", "correct": false, "because": "Nicht beteiligt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Einhaltung unwichtig?', 3, '[{"text": "Gesetzeskenntnis", "correct": false, "because": "Grundlage der Regeln"}, {"text": "Überprüfung", "correct": false, "because": "Sichert Einhaltung"}, {"text": "Kaffeepausen", "correct": true, "because": "Kein rechtlicher Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Gilt Compliance auch für Software?', 3, '[{"text": "Ja", "correct": true, "because": "Lizenz- und Datenvorgaben"}, {"text": "Nein", "correct": false, "because": "Teil der IT-Regeln"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob es nur nationale Regeln betrifft?', 2, '[{"text": "Nein", "correct": true, "because": "Auch internationale Vorgaben"}, {"text": "Ja", "correct": false, "because": "Globaler Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool hilft mir bei der Umsetzung?', 4, '[{"text": "Audit-Software", "correct": true, "because": "Prüft Einhaltung"}, {"text": "Grafikprogramm", "correct": false, "because": "Kein Zusammenhang"}, {"text": "Spieleplattform", "correct": false, "because": "Irrelevant"}]');
